MOD = 10**9 + 7

def count_ways(n):
    total_ways = pow(3, 3 * n, MOD)

    def count_unsatisfied_ways():
        unsatisfied_ways = 0
        for a in range(1, 4):
            for b in range(1, 4):
                for c in range(1, 4):
                    if a + b + c == 6:
                        unsatisfied_ways += pow(3, 3 * n - 3, MOD)
                        unsatisfied_ways %= MOD
        return unsatisfied_ways

    unsatisfied_ways = count_unsatisfied_ways()
    satisfied_ways = (total_ways - unsatisfied_ways) % MOD
    return satisfied_ways

